"""Test cases for plugin output."""

from azul_runner import (
    DataLabel,
    FV,
    Event,
    EventData,
    JobResult,
    State,
    test_template,
)

from azul_plugin_ghidra.main import AzulPluginGhidra


class TestExecute(test_template.TestPlugin):
    """Run tests."""

    PLUGIN_TO_TEST = AzulPluginGhidra

    def test_opt_out(self):
        """Test for a case where the program should opt-out."""
        data = self.load_test_file_bytes(
            "cd8764f579d38406fe77ab8ebcc4cec82e3ceef1d769ea2e9b84a866b6d0a119",
            "Malicious Windows 32EXE key logger and credential stealer.",
        )
        result = self.do_execution(data_in=[("content", data)])
        self.assertJobResult(
            result,
            JobResult(state=State(State.Label.OPT_OUT, message="Unable to open binary in Ghidra Headless Mode.")),
        )

    def test_file_too_large(self):
        """Test for a case where the program should opt-out because the file is too large."""
        data = self.load_test_file_bytes(
            "da31c224edcb9520afa6a0df89c0cc32eac07b5d8e8bc2816c3e55764738a117",
            "OBS-Studio-32.0.2-Windows-x64-Installer.",
        )
        result = self.do_execution(data_in=[("content", data)])
        self.assertJobResult(
            result,
            JobResult(state=State(State.Label.OPT_OUT, message="Unable to open binary in Ghidra Headless Mode.")),
        )

